// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // Your Cal.com username (from cal.com/<username>/<event>)
    cal_username: "danielle-traynor-hc7i3n",
    // The event type to book (the last part of your booking link)
    event_type_slug: "30min",
    // Your time zone, e.g. America/New_York, America/Chicago, America/Los_Angeles
    timezone: "America/New_York",
    // Optional. Leave empty for a public booking page; otherwise paste a cal_live_... key
    cal_api_key: "",
    // How many days ahead to look for openings
    days_to_search: 14,
  },
}];

const req = $('Vapi Tool Call').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};
const toolCall =
  (msg.toolCallList ?? msg.toolCalls ?? [])[0] ??
  msg.toolWithToolCallList?.[0]?.toolCall ?? {};
// Function tools send Vapi's tool-call envelope; API Request tools POST the
// parameters as the whole body.
let args = toolCall.function?.arguments ?? toolCall.arguments ?? (body.message ? {} : body);
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { args = {}; }
}
const toolCallId = toolCall.id ?? '';

const cfg = $('Config').first().json;
let from = DateTime.now().setZone(cfg.timezone).startOf('day');
if (args.requested_date) {
  const d = DateTime.fromISO(String(args.requested_date), { zone: cfg.timezone });
  if (d.isValid && d >= from) from = d.startOf('day');
}
const to = from.plus({ days: Number(cfg.days_to_search) || 14 }).endOf('day');
return [{
  json: {
    tool_call_id: toolCallId,
    start: from.toUTC().toISO(),
    end: to.toUTC().toISO(),
  },
}];

const cfg = $('Config').first().json;
const res = $input.first().json;
const byDay = res.status === 'success' && res.data && typeof res.data === 'object' ? res.data : null;
const all = byDay
  ? Object.values(byDay).flat()
      .map((s) => DateTime.fromISO(typeof s === 'string' ? s : s.start, { setZone: true }))
      .filter((t) => t.isValid)
      .sort((a, b) => a - b)
  : [];

// Offer two options at least an hour apart (or on different days) so the caller gets a real choice.
const found = [];
for (const t of all) {
  if (found.length === 2) break;
  if (!found.length || t >= found[0].plus({ minutes: 60 }) || !t.hasSame(found[0], 'day')) found.push(t);
}

let result;
if (!byDay) {
  result = "The calendar couldn't be checked right now. Tell the caller the team will call today to set a time.";
} else if (!found.length) {
  result = 'No openings in the next two weeks. Tell the caller the team will call to find a time that works.';
} else {
  const spoken = found.map((t, i) => {
    const local = t.setZone(cfg.timezone);
    return `Option ${i + 1}: ${local.toFormat("cccc, LLLL d 'at' h:mm a")} (start_time ${local.toISO()})`;
  }).join('. ');
  result = `Open times (${cfg.timezone}): ${spoken}. Offer these in words. ` +
    'If the caller picks one, get their email, then call bookStrategyCall with that start_time.';
}
return [{ json: { tool_call_id: $('Parse Tool Call').first().json.tool_call_id, result } }];
